        x if x % 2 == 0 => println!("even"),
        x if x > 5 => println!("big odd {x}"),
        _ => println!("small odd"),
    }
}

fn describe(v: &[i32]) -> &str {
    match v {
        [] => "empty",
        [_] => "one",
        [a, .., b] if a == b => "same ends",
        _ => "other",
    }
}

